# This section is for verification/confirmation of the logic, not direct calculation of solutions,
# as the manual algebraic checks were exhaustive for the given small cases.
# We confirm the structure of the check.

def check_n2(p):
    # Check C1 + C2 * p = 0, where C1, C2 in {-2, -1, 1, 2}
    for C1 in range(-2, 3):
        for C2 in range(-2, 3):
            if C2 == 0:
                continue
            if abs(C1 / C2 - p) < 1e-9:
                return True, (C1, C2)
    return False, None

def check_n3(p):
    # Check C1 + C2 * p + C3 * p^2 = 0, where C1, C2, C3 in {-2, -1, 1, 2} (C3 != 0)
    for C3 in range(-2, 3):
        if C3 == 0:
            continue
        for C2 in range(-2, 3):
            for C1 in range(-2, 3):
                if abs(C1 + C2 * p + C3 * p**2) < 1e-9:
                    return True, (C1, C2, C3)
    return False, None

ps_to_check = [3/2, 2/3, 4/3]
results = {}

for p in ps_to_check:
    results[p] = {}
    found_n2, coeffs_n2 = check_n2(p)
    results[p]['N=2'] = (found_n2, coeffs_n2)
    found_n3, coeffs_n3 = check_n3(p)
    results[p]['N=3'] = (found_n3, coeffs_n3)

print("Results:")
for p, res in results.items():
    print(f"\n--- p = {p} ---")
    print(f"N=2 check: Found={res['N=2'][0]}, Coeffs={res['N=2'][1]}")
    print(f"N=3 check: Found={res['N=3'][0]}, Coeffs={res['N=3'][1]}")
